def word_frequency(text: str) -> dict[str, int]:
    counts = {}
    for raw in text.split():
        start = 0
        end = len(raw)

        while start < end and not raw[start].isalnum():
            start += 1
        while end > start and not raw[end - 1].isalnum():
            end -= 1

        word = raw[start:end].lower()
        if word:
            counts[word] = counts.get(word, 0) + 1

    return counts
